from auto_config.generator.vcu.managed_objects.managed_object import ManagedObject


class NradjnrcellParamsGenerator(ManagedObject):

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.nradjnrcell_ent = self.enb_ent_config['nradjnrcell'][self.mo_num]

    def _prepare_section_content(self, execution_config, *args, **kwargs):
        mcc, mnc = self.nradjnrcell_ent['mcc'], self.nradjnrcell_ent['mnc']

        self.set_struct_parameter('gnbPlmn', [
            {
                'mcc': mcc,
                'mnc': mnc,
                'mncLength': self.get_len_str(mnc),
            }
        ])
        self.set_parameter('cellDepType', self.nradjnrcell_ent['type'])
        self.set_parameter('gNbId', self.nradjnrcell_ent['gnb_id'])
        self.set_parameter('lcrId', self.nradjnrcell_ent['lcr_id'])
        self.set_parameter('nrarfcn', self.nradjnrcell_ent['earfcn'])
        self.set_parameter('physCellId', self.nradjnrcell_ent['pci'])
        self.set_parameter('ssbFrequency', self.nradjnrcell_ent['ssb_frequency'])
